/// <summary>
/// Creates a sales release line.
/// </summary>
public void createSalesLine()
{
    salesLine.AVARUMMemoProduction = createFromAgreementLine.AVARUMMemoProduction;
    salesLine.AVARUMMemoBlanket = createFromAgreementLine.AVARUMMemoBlanket;

    next createSalesLine();
}
